using System.Windows; using BioVic.Desktop.Converters; using BioVic.Desktop.Services; using BioVic.Domain.Enums;
namespace BioVic.Desktop.Views;
public partial class IncidentWindow:Window{private readonly BioVicApiClient _client;private readonly Guid _id;public IncidentWindow(BioVicApiClient client,Guid id){InitializeComponent();_client=client;_id=id;DateBox.SelectedDate=DateTime.Today;StatusBox.ItemsSource=SpanishLabels.Options<IncidentStatus>();StatusBox.DisplayMemberPath="Text";StatusBox.SelectedValuePath="Value";StatusBox.SelectedValue=IncidentStatus.Open;}private async void Save_Click(object s,RoutedEventArgs e){try{await _client.AddIncidentAsync(_id,new(ToUtc(DateBox.SelectedDate)??DateTimeOffset.UtcNow,TypeBox.Text,DescriptionBox.Text,ConsequenceBox.Text,ReportedByBox.Text,StatusBox.SelectedValue is IncidentStatus status?status:IncidentStatus.Open,ActionsBox.Text,ExternalBox.IsChecked==true,ExternalNumberBox.Text,ToUtc(ExternalDateBox.SelectedDate),EntityBox.Text,ConclusionsBox.Text));DialogResult=true;}catch(Exception ex){ErrorText.Text=ex.Message;}}private static DateTimeOffset? ToUtc(DateTime? d)=>d is null?null:new DateTimeOffset(d.Value).ToUniversalTime();private void Cancel_Click(object s,RoutedEventArgs e)=>DialogResult=false;}
